}

tests:
package exercise

import "testing"

func TestHello(t *testing.T) {
	tests := []struct {
		name string
		want string
	}{
		{name: "Chris", want: "Hello, Chris"},
		{name: "", want: "Hello, World"},
	}
	for _, tt := range tests {
		got := Hello(tt.name)
		if got != tt.want {
			t.Fatalf("Hello(%q) = %q, want %q", tt.name, got, tt.want)
		}
	}
}

solution:
package exercise

func Hello(name string) string {
	if name == "" {
		name = "World"
	}
	return "Hello, " + name
}

