package exercise

func Repeat(character string, count int) string {
	return ""
}

tests:
package exercise

import "testing"

func TestRepeat(t *testing.T) {
	got := Repeat("a", 5)
	want := "aaaaa"
	if got != want {
		t.Fatalf("Repeat returned %q, want %q", got, want)
	}
	if got := Repeat("b", 0); got != "" {
		t.Fatalf("Repeat with zero count returned %q, want empty string", got)
	}
}

solution:
package exercise

func Repeat(character string, count int) string {
	var repeated string
	for i := 0; i < count; i++ {
		repeated += character
	}
	return repeated
}

