func Sum(numbers []int) int {
	return 0
}

tests:
package exercise

import "testing"

func TestSum(t *testing.T) {
	tests := []struct {
		numbers []int
		want    int
	}{
		{numbers: []int{1, 2, 3, 4, 5}, want: 15},
		{numbers: []int{}, want: 0},
	}
	for _, tt := range tests {
		if got := Sum(tt.numbers); got != tt.want {
			t.Fatalf("Sum(%v) = %d, want %d", tt.numbers, got, tt.want)
		}
	}
}

solution:
package exercise

func Sum(numbers []int) int {
	total := 0
	for _, number := range numbers {
		total += number
	}
	return total
}

